int amd_gpio_driver_probe(struct platform_device *pdev)
{
    struct gpio_device *gpio_dev;
    struct resource *res;
    void __iomem *base;
    int ret, irq;

    gpio_dev = kzalloc(sizeof(*gpio_dev), GFP_KERNEL);
    if (!gpio_dev)
        return -ENOMEM;

    mutex_init(&gpio_dev->lock);

    res = platform_get_resource(pdev, IORESOURCE_MEM, 0);
    if (!res) {
        ret = -ENODEV;
        goto free_gpio_dev;
    }

    base = devm_ioremap_resource(&pdev->dev, res);
    if (IS_ERR(base)) {
        ret = PTR_ERR(base);
        goto free_gpio_dev;
    }
    gpio_dev->regs = base;

    irq = platform_get_irq(pdev, 0);
    if (irq < 0) {
        ret = irq;
        goto free_gpio_dev;
    }

    gpio_dev->chip.label = "amd_gpio";
    gpio_dev->chip.direction_input = amd_gpio_direction_input;
    gpio_dev->chip.direction_output = amd_gpio_direction_output;
    gpio_dev->chip.get = amd_gpio_get;
    gpio_dev->chip.set = amd_gpio_set;
    gpio_dev->chip.dbg_write = amd_gpio_dbg_write;
    gpio_dev->chip.can_sleep = false;

    ret = devm_gpiochip_add_data(&pdev->dev, &gpio_dev->chip, gpio_dev);
    if (ret) {
        dev_err(&pdev->dev, "Failed to register GPIO chip\n");
        goto free_gpio_dev;
    }

    ret = devm_gpiochip_register(&pdev->dev, &gpio_dev->chip);
    if (ret) {
        dev_err(&pdev->dev, "Failed to register GPIO pin control driver\n");
        goto free_gpio_dev;
    }

    platform_set_drvdata(pdev, gpio_dev);
    dev_info(&pdev->dev, "AMD GPIO driver loaded successfully\n");
    return 0;

free_gpio_dev:
    kfree(gpio_dev);
    return ret;
}

int amdgpio_probe(struct platform_device *pdev)
{
    struct gpio_chip *gpio_chip;
    struct resource *res;
    void __iomem *regs;
    int irq, ret;

    gpio_chip = devm_kzalloc(&pdev->dev, sizeof(*gpio_chip), GFP_KERNEL);
    if (!gpio_chip)
        return -ENOMEM;

    spin_lock_init(&gpio_chip->lock);

    res = platform_get_resource(pdev, IORESOURCE_MEM, 0);
    regs = devm_ioremap_resource(&pdev->dev, res);
    if (IS_ERR(regs))
        return PTR_ERR(regs);

    gpio_chip->regbase = regs;
    gpio_chip->ngpio = 32; /* Example value, adjust as needed */
    gpio_chip->label = "AMD_GPIO";

    gpio_chip->set_direction_input = amdgpio_set_direction_input;
    gpio_chip->set_direction_output = amdgpio_set_direction_output;
    gpio_chip->get = amdgpio_get;
    gpio_chip->set = amdgpio_set;
    gpio_chip->set_config = amdgpio_set_config;

    irq = platform_get_irq(pdev, 0);
    if (irq < 0)
        return irq;

    ret = devm_gpiochip_add_data(&pdev->dev, gpio_chip, NULL);
    if (ret) {
        dev_err(&pdev->dev, "Failed to add GPIO chip: %d\n", ret);
        return ret;
    }

    ret = devm_request_irq(&pdev->dev, irq, amdgpio_irq_handler,
                             IRQF_SHARED, "amdgpio", gpio_chip);
    if (ret) {
        dev_err(&pdev->dev, "Failed to request IRQ: %d\n", ret);
        return ret;
    }

    dev_info(&pdev->dev, "AMD GPIO driver loaded\n");
    return 0;
}

#include <linux/platform_device.h>
#include <linux/gpio.h>
#include <linux/io.h>
#include <linux/irq.h>
#include <linux/module.h>
#include <linux/slab.h>

int amd_gpio_probe(struct platform_device *pdev)
{
    struct gpio_chip *chip;
    struct resource *mem;
    void __iomem *regs;
    int irq, ret;

    chip = kzalloc(sizeof(*chip), GFP_KERNEL);
    if (!chip)
        return -ENOMEM;

    mem = platform_get_resource(pdev, IORESOURCE_MEM, 0);
    if (!mem) {
        ret = -ENODEV;
        goto err_free_chip;
    }

    regs = ioremap(mem->start, resource_size(mem));
    if (!regs) {
        ret = -ENOMEM;
        goto err_free_chip;
    }

    spin_lock_init(&chip->lock);

    irq = platform_get_irq(pdev, 0);
    if (irq < 0) {
        ret = irq;
        goto err_unmap;
    }

    chip->label = "AMD_GPIO";
    chip->owner = THIS_MODULE;
    chip->base = -1;
    chip->ngpio = 32;
    chip->can_sleep = false;
    chip->request_gpio = NULL;
    chip->free_gpio = NULL;
    chip->direction_input = NULL;
    chip->direction_output = NULL;
    chip->get = NULL;
    chip->set = NULL;

    ret = gpiochip_add(chip);
    if (ret < 0)
        goto err_unmap;

    platform_set_drvdata(pdev, chip);

    dev_info(&pdev->dev, "AMD GPIO driver loaded\n");

    return 0;

err_unmap:
    iounmap(regs);
err_free_chip:
    kfree(chip);
    return ret;
}

int amd_gpio_driver_probe(struct platform_device *pdev)
{
    struct gpio_chip *gc;
    struct resource *mem;
    void __iomem *base;
    int irq, ret;

    gc = kzalloc(sizeof(*gc), GFP_KERNEL);
    if (!gc)
        return -ENOMEM;

    spin_lock_init(&gc->irq_lock);

    mem = platform_get_resource(pdev, IORESOURCE_MEM, 0);
    if (!mem) {
        ret = -ENODEV;
        goto free_gc;
    }

    base = devm_ioremap_resource(&pdev->dev, mem);
    if (IS_ERR(base)) {
        ret = PTR_ERR(base);
        goto free_gc;
    }

    irq = platform_get_irq(pdev, 0);
    if (irq < 0) {
        ret = irq;
        goto free_gc;
    }

    gc->label = "AMD GPIO";
    gc->owner = THIS_MODULE;
    gc->base = -1;
    gc->ngpio = 32;
    gc->can_sleep = false;
    gc->set = amd_gpio_set;
    gc->direction_input = amd_gpio_dir_in;
    gc->direction_output = amd_gpio_dir_out;
    gc->get = amd_gpio_get;
    gc->debounce_set = amd_gpio_set_debounce;

    ret = gpiochip_add_data(gc, NULL);
    if (ret) {
        dev_err(&pdev->dev, "Failed to add gpio chip\n");
        goto free_gc;
    }

    platform_set_drvdata(pdev, gc);

    dev_info(&pdev->dev, "AMD GPIO driver loaded successfully\n");

    return 0;

free_gc:
    kfree(gc);
    return ret;
}

